const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI energy management arbitrator for community EV charging plazas. You analyze transformer load curves, active vehicle charging sessions, battery state of charge (SoC), and Time-of-Day (ToD) electricity tariffs to prevent grid overloads and maximize off-peak cost savings.

Analyze the input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{
  "gridLoadStatus": "OPTIMAL",
  "currentTransformerUtilizationPercent": 64.2,
  "activeSessionsCount": 8,
  "throttledBaysCount": 0,
  "estimatedCostSavingsRupees": 480,
  "recommendedChargingQueue": [
    { "bayId": "EV-BAY-01", "allocatedKw": 7.4, "priority": "HIGH_SOC_NEEDED", "status": "FAST_CHARGING" },
    { "bayId": "EV-BAY-02", "allocatedKw": 3.3, "priority": "OVERNIGHT_STANDBY", "status": "TRICKLE_SAVER" }
  ],
  "peakLoadDirectives": "Transformer headroom safe at 35.8%. Maintain full 7.4kW allocation across all active slots until peak hour 18:00."
}

Rules:
- gridLoadStatus must be one of: "OPTIMAL", "APPROACHING_THRESHOLD", "PEAK_THROTTLED", "EMERGENCY_SHEDDING".
- Return pure JSON only, no markdown wrapping.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"gridLoadStatus":"OPTIMAL","currentTransformerUtilizationPercent":64.2,"activeSessionsCount":8,"throttledBaysCount":0,"estimatedCostSavingsRupees":480,"recommendedChargingQueue":[{"bayId":"EV-BAY-01","allocatedKw":7.4,"priority":"HIGH_SOC_NEEDED","status":"FAST_CHARGING"},{"bayId":"EV-BAY-02","allocatedKw":3.3,"priority":"OVERNIGHT_STANDBY","status":"TRICKLE_SAVER"}],"peakLoadDirectives":"Transformer headroom safe at 35.8%. Maintain full 7.4kW allocation across all active slots until peak hour 18:00."} } }];
}
